}

// 1) ?????????? PDF
const buyerAddr = pdf.buyer_address_raw;

// 2) ?????????? API (???????????????????)
let apiAddr = api.address_raw;
if (!apiAddr && api.address) {
  const a = api.address;
  const parts = [];
  if (a.houseNo) parts.push(a.houseNo);
  if (a.moo) parts.push(`???? ${a.moo}`);
  if (a.subDistrict) parts.push(`????${a.subDistrict}`);
