}

// Normalize ???????????
const normBuyer = normalizeThaiAddress(buyerAddr);
const normApi   = normalizeThaiAddress(apiAddr);

// --- Logic ????: Bidirectional Check (???? 2 ???) ---
let buyer_address_status = false;

if (normBuyer && normApi) {
  // ?????????? 1: ???? PDF ???? API ???????
  const pdfInApi = isSubset(normBuyer, normApi);

  // ?????????? 2: ???? API ???? PDF ???????
  const apiInPdf = isSubset(normApi, normBuyer);

